/**
 * The http binding: `HeedApi` over the Heed service, through a client typed from the API contract
 * (src/contract). It needs the contract's routes only, not its schemas (the service validates),
 * so it reads them from `contract.json`, generated by `npm run api:generate`. Loaded on demand.
 *
 * Wired so far: the session, the workspace's people and domains, Context (the list with the
 * drafts, an item's page, the editor's publish and suggestion, changes to many items, P7c),
 * Definitions with the terms and synonyms written here (P7b, P7c), search everywhere, comments
 * with their reactions and mentions, the Inbox and the review (the golden plan's P6b), Ask on the
 * answer engine, with the person's chats kept in their browser (P10, http-ask.ts), and People:
 * Admin and Member, a domain's owners, invites with their links, removing someone, and how the
 * sign-in screen signs people in (P8, http-people.ts). Every other method answers `not-available`
 * until the pull request that wires its screen (P9 to P13). The conformance suite
 * (tests/app/conformance/heed-api.ts) runs the wired ones. Changes carry the session's token in
 * `X-Heed-CSRF`, as the service requires, and a retry key, kept until the service answers; the
 * session cookie is HttpOnly, so the token is read from `auth.session`.
 */
import { createORPCClient } from '@orpc/client'
import type { AnyContractRouter, ContractRouterClient } from '@orpc/contract'
import { OpenAPILink } from '@orpc/openapi-client/fetch'
import type { Asked, LookupEvent } from '@contract/answer'
import type { Contract } from '@contract/index'
import type { Feed } from '@contract/inbox'
import type { ProposalRecord } from '@contract/proposals'
