  'restoreAsDraft',
  'markViewed',
  'editItem',
  'saveItem',
  'draftFromText',
  'applyBulk',
  'sendSuggestion',
  'withdrawSuggestion',
  'getDefinitions',
  'definitionsPage',
  'definitionPage',
